import{_ as t,r as a,o as c,c as o,e as n,a as l,s as r}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"哈希和加密 - October CMS - 3.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"配置","slug":"配置","link":"#配置","children":[]},{"level":2,"title":"哈希","slug":"哈希","link":"#哈希","children":[{"level":4,"title":"验证密码与哈希值是否匹配","slug":"验证密码与哈希值是否匹配","link":"#验证密码与哈希值是否匹配","children":[]},{"level":4,"title":"检查密码是否需要重新哈希","slug":"检查密码是否需要重新哈希","link":"#检查密码是否需要重新哈希","children":[]}]},{"level":2,"title":"加密","slug":"加密","link":"#加密","children":[{"level":4,"title":"解密值","slug":"解密值","link":"#解密值","children":[]}]}],"relativePath":"3.x/zh-cn/extend/services/hash-crypt.md","filePath":"3.x/zh-cn/extend/services/hash-crypt.md"}'),i={name:"3.x/zh-cn/extend/services/hash-crypt.md"};function u(k,s,d,h,g,m){const e=a("pre-heading"),p=a("post-heading");return c(),o("div",null,[n(e),s[0]||(s[0]=l("h1",null,"哈希和加密",-1)),n(p),s[1]||(s[1]=r(`<h2 id="配置"><a href="#配置" class="header-anchor">#</a> 配置</h2><p>首次安装 October 时，应该已经为你生成了一个随机密钥。你可以通过检查 <code>config/app.php</code> 配置文件中的 <code>key</code> 选项来确认。如果密钥保持不变，你应该将其设置为 32 个字符的随机字符串。如果此值未正确设置，所有加密值将不安全。</p><h2 id="哈希"><a href="#哈希" class="header-anchor">#</a> 哈希</h2><p><code>Hash</code> 门面提供安全的 Bcrypt 哈希，用于存储用户密码。Bcrypt 是哈希密码的绝佳选择，因为其&quot;工作因子&quot;是可调的，这意味着随着硬件能力的增加，生成哈希所需的时间也可以增加。</p><p>你可以通过在 <code>Hash</code> 门面上调用 <code>make</code> 方法来对密码进行哈希处理：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">User</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">password</span> <span class="token operator">=</span> <span class="token class-name static-context">Hash</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;mypassword&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>或者，模型可以实现 <a href="./../database/traits.html">Hashable trait</a> 来自动对属性进行哈希处理。</p><h4 id="验证密码与哈希值是否匹配"><a href="#验证密码与哈希值是否匹配" class="header-anchor">#</a> 验证密码与哈希值是否匹配</h4><p><code>check</code> 方法允许你验证给定的明文字符串是否与给定的哈希值对应。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">Hash</span><span class="token operator">::</span><span class="token function">check</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;plain-text&#39;</span><span class="token punctuation">,</span> <span class="token variable">$hashedPassword</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// 密码匹配...</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="检查密码是否需要重新哈希"><a href="#检查密码是否需要重新哈希" class="header-anchor">#</a> 检查密码是否需要重新哈希</h4><p><code>needsRehash</code> 函数允许你确定哈希器使用的工作因子自密码被哈希以来是否已更改：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">Hash</span><span class="token operator">::</span><span class="token function">needsRehash</span><span class="token punctuation">(</span><span class="token variable">$hashed</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$hashed</span> <span class="token operator">=</span> <span class="token class-name static-context">Hash</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;plain-text&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="加密"><a href="#加密" class="header-anchor">#</a> 加密</h2><p>你可以使用 <code>Crypt</code> 门面加密值。所有加密值都使用 OpenSSL 和 <code>AES-256-CBC</code> 密码进行加密。此外，所有加密值都使用消息认证码（MAC）进行签名，以检测加密字符串的任何修改。</p><p>例如，我们可以使用 <code>encrypt</code> 方法加密一个秘密并将其存储在<a href="./../database/model.html">数据库模型</a>中：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">User</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">secret</span> <span class="token operator">=</span> <span class="token class-name static-context">Crypt</span><span class="token operator">::</span><span class="token function">encrypt</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;shhh no telling&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="解密值"><a href="#解密值" class="header-anchor">#</a> 解密值</h4><p>当然，你可以使用 <code>Crypt</code> 门面上的 <code>decrypt</code> 方法解密值。如果值无法正确解密（例如 MAC 无效时），将抛出 <code>Illuminate\\Contracts\\Encryption\\DecryptException</code> 异常：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">use</span> <span class="token package">Illuminate<span class="token punctuation">\\</span>Contracts<span class="token punctuation">\\</span>Encryption<span class="token punctuation">\\</span>DecryptException</span><span class="token punctuation">;</span>

<span class="token keyword">try</span> <span class="token punctuation">{</span>
    <span class="token variable">$decrypted</span> <span class="token operator">=</span> <span class="token class-name static-context">Crypt</span><span class="token operator">::</span><span class="token function">decrypt</span><span class="token punctuation">(</span><span class="token variable">$encryptedValue</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token keyword">catch</span> <span class="token punctuation">(</span><span class="token class-name">DecryptException</span> <span class="token variable">$ex</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span>
</code></pre></div><p>或者，模型可以实现 <a href="./../database/traits.html">Encryptable trait</a> 来自动加密和解密属性。</p>`,21))])}const f=t(i,[["render",u]]);export{y as __pageData,f as default};
